/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero budget is invalid according to the configuration contract; treating
    // it as one attempt keeps the runner from silently skipping the job.
    let max_attempts = config.max_attempts.max(1);
    let mut delay = config.base_delay_ms;

    for attempt in 0..max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt + 1 == max_attempts => {
                return Err(error)
            }
            Err(_) => {
                sleeper.sleep_ms(delay.min(config.max_delay_ms));
                delay = delay
                    .saturating_mul(2)
                    .min(config.max_delay_ms);
            }
        }
    }

    unreachable!("max_attempts is always at least one")
}

