fn public_runner_retries_then_succeeds() {
    let config = RetryConfig::new(3, 7, 20);
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        match attempts {
            1 | 2 => Err(RetryError::Transient("temporary".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![7, 14]);
}

